typedef unsigned long long big_int;

#define STRINGX_MAX_SHORT_STRINGS 15000
#define STRINGX_MAX_MEDIUM_STRINGS 7000
#define STRINGX_MAX_LONG_STRINGS 100
#define STRINGX_SHORT_STRING_MAX_LENGTH 32
#define STRINGX_MEDIUM_STRING_MAX_LENGTH 80
#define STRINGX_LONG_STRING_MAX_LENGTH 1024
#define STRINGX_DEBUG
#define assert(expression) ((void)0)

class stringx;

class string_buf {
protected:
    friend class stringx;
    big_int *data;
    int ref_count;
    int char_length;
    int block_length;
    int max_blocks;

public:
    inline void inc_ref() { ref_count++; }
    inline int get_ref() { return ref_count; }
    void clear();
};

class stringx {
    static unsigned int free_small_buffers_end;
    static unsigned int free_medium_buffers_end;
    static unsigned int free_long_buffers_end;
    static string_buf *find_small_buffer();
    static string_buf *find_medium_buffer();
    static string_buf *find_large_buffer();

public:
    static string_buf *find_empty_buffer(
        int capacity,
        const char *str_just_for_error_msgs);
};

extern unsigned int peak_small_strings;
extern unsigned int peak_medium_strings;
extern unsigned int peak_long_strings;
extern "C" void report_error(const char *, ...) __asm__("error__FPCce");
extern const char string_too_long[];

__asm__(".equ clear__10string_buf, 0x0034D358");
__asm__(".equ find_small_buffer__7stringx, 0x0034DB50");
__asm__(".equ find_medium_buffer__7stringx, 0x0034DBB8");
__asm__(".equ find_large_buffer__7stringx, 0x0034DC20");
__asm__(".equ error__FPCce, 0x001DFBD8");
__asm__(".equ peak_small_strings, 0x0046ED34");
__asm__(".equ peak_medium_strings, 0x0046ED38");
__asm__(".equ peak_long_strings, 0x0046ED3C");
__asm__(".equ _7stringx$free_small_buffers_end, 0x005121C0");
__asm__(".equ _7stringx$free_medium_buffers_end, 0x005121C4");
__asm__(".equ _7stringx$free_long_buffers_end, 0x005121C8");
__asm__(".equ string_too_long, 0x00503368");

string_buf *stringx::find_empty_buffer(
    int capacity,
    const char *str_just_for_error_msgs)
{
    string_buf *tmpbuf = 0;

    if (capacity < STRINGX_SHORT_STRING_MAX_LENGTH - 1)
        tmpbuf = find_small_buffer();
    else if (capacity < STRINGX_MEDIUM_STRING_MAX_LENGTH - 1)
        tmpbuf = find_medium_buffer();
    else if (capacity < STRINGX_LONG_STRING_MAX_LENGTH - 1)
        tmpbuf = find_large_buffer();
    else
        report_error(string_too_long, str_just_for_error_msgs);

    assert(tmpbuf);
    assert(tmpbuf->get_ref() == 0);
    assert(tmpbuf->data != 0);

    tmpbuf->clear();

#ifdef STRINGX_DEBUG
    int cur_small_strings =
        STRINGX_MAX_SHORT_STRINGS - free_small_buffers_end;
    int cur_medium_strings =
        STRINGX_MAX_MEDIUM_STRINGS - free_medium_buffers_end;
    int cur_long_strings =
        STRINGX_MAX_LONG_STRINGS - free_long_buffers_end;
    if (peak_small_strings < (unsigned)cur_small_strings)
        peak_small_strings = cur_small_strings;
    if (peak_medium_strings < (unsigned)cur_medium_strings)
        peak_medium_strings = cur_medium_strings;
    if (peak_long_strings < (unsigned)cur_long_strings)
        peak_long_strings = cur_long_strings;
#endif

    tmpbuf->inc_ref();
    assert(tmpbuf->get_ref() == 1);

    return tmpbuf;
}
